INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('2942d065-52fb-4064-9724-005812bd305f','e9ebefcd-c496-45e8-b816-a79f8442ba85',4.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('2942d065-52fb-4064-9724-005812bd305f','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$Council Member Snell focuses on public safety by fully funding first responders to reduce emergency response times, and as DTSM board chair was a vocal advocate on Promenade and downtown safety — an enforcement-supportive posture.$$,ARRAY['https://www.santamonica.gov/elections/2024-11-05/candidates/barry-a-snell']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('2942d065-52fb-4064-9724-005812bd305f','669cac97-66a6-4087-b036-936fbe62efb3',2.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('2942d065-52fb-4064-9724-005812bd305f','669cac97-66a6-4087-b036-936fbe62efb3',$$Snell supports easing affordable-housing construction by streamlining bureaucratic processes and, as a college trustee, took direct action to build affordable housing to keep students out of homelessness.$$,ARRAY['https://www.santamonica.gov/elections/2024-11-05/candidates/barry-a-snell']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('2942d065-52fb-4064-9724-005812bd305f','d4f18138-a2e0-4110-b925-7387d9d0d16d',4.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('2942d065-52fb-4064-9724-005812bd305f','d4f18138-a2e0-4110-b925-7387d9d0d16d',$$Snell joined the Council's unanimous vote to delay state housing law SB 79 in displacement-vulnerable areas like Pico until 2030 while developing an alternative redirecting density toward transit corridors — a position protecting vulnerable neighborhoods from state-mandated upzoning.$$,ARRAY['https://www.smdp.com/santa-monica-council-moves-to-soften-state-housing-laws-impact-on-vulnerable-neighborhoods/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
